     mc("Persona 4", ["Acepta las tasas con una condición.", "Rechaza cualquier tasa.", "Quiere tasas más altas."], 0),
     mc("Persona 5", ["Defiende el valor de viajar.", "Cree que hay que dejar de viajar.", "Viaja solo por trabajo."], 0),
